<?php
require_once __DIR__.'/../includes/init.php';require_login();$page_title='Exam Marks';$students=$pdo->query("SELECT id,admission_no,full_name FROM students WHERE status='active' ORDER BY full_name")->fetchAll();$exams=$pdo->query('SELECT id,exam_name FROM examinations ORDER BY id DESC')->fetchAll();$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();try{$q=$pdo->prepare('INSERT INTO exam_marks(examination_id,student_id,subject_name,total_marks,obtained_marks,entered_by) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE total_marks=VALUES(total_marks),obtained_marks=VALUES(obtained_marks),entered_by=VALUES(entered_by)');$q->execute([(int)$_POST['exam_id'],(int)$_POST['student_id'],trim($_POST['subject']), (float)$_POST['total'],(float)$_POST['obtained'],$_SESSION['user_id']]);flash('Marks saved.');go('exams/marks.php');}catch(Throwable $e){$err='Could not save marks. Obtained marks cannot exceed total marks.';}}
$rows=$pdo->query('SELECT m.*,s.full_name,e.exam_name FROM exam_marks m JOIN students s ON s.id=m.student_id JOIN examinations e ON e.id=m.examination_id ORDER BY m.id DESC LIMIT 200')->fetchAll();require __DIR__.'/../includes/header.php';?><h1>Examination Marks</h1><?php if($err):?><div class="notice error"><?=h($err)?></div><?php endif;?><div class="panel"><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><div class="formgrid"><div><label>Exam</label><select name="exam_id" required><?php foreach($exams as $e):?><option value="<?=$e['id']?>"><?=h($e['exam_name'])?></option><?php endforeach;?></select></div><div><label>Student</label><select name="student_id" required><?php foreach($students as $s):?><option value="<?=$s['id']?>"><?=h($s['admission_no'].' - '.$s['full_name'])?></option><?php endforeach;?></select></div><div><label>Subject</label><input name="subject" required></div><div><label>Total marks</label><input type="number" step=".01" min=".01" name="total" required></div><div><label>Obtained marks</label><input type="number" step=".01" min="0" name="obtained" required></div></div><button>Save marks</button></form></div><div class="panel"><table><tr><th>Exam</th><th>Student</th><th>Subject</th><th>Obtained</th><th>Total</th><th>%</th></tr><?php foreach($rows as $r):?><tr><td><?=h($r['exam_name'])?></td><td><?=h($r['full_name'])?></td><td><?=h($r['subject_name'])?></td><td><?=h($r['obtained_marks'])?></td><td><?=h($r['total_marks'])?></td><td><?=number_format(100*$r['obtained_marks']/$r['total_marks'],2)?>%</td></tr><?php endforeach;?></table></div><?php require __DIR__.'/../includes/footer.php';?>